    Bug 1952094 - Convert nsParseNewMailState to use nsIMsgDatabase.attachHdr(). r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D251457

diff --git a/mailnews/local/src/nsParseMailbox.cpp b/mailnews/local/src/nsParseMailbox.cpp
index 83893276724..fe25166d20b 100644
--- a/mailnews/local/src/nsParseMailbox.cpp
+++ b/mailnews/local/src/nsParseMailbox.cpp
@@ -1367,7 +1367,13 @@ void nsParseNewMailState::PublishMsgHeader(nsIMsgWindow* msgWindow) {
     }
     if (!moved) {
       if (m_mailDB) {
-        m_mailDB->AddNewHdrToDB(m_newMsgHdr, true);
+        nsresult rv =
+            m_mailDB->AttachHdr(m_newMsgHdr, true, getter_AddRefs(m_newMsgHdr));
+        if (NS_FAILED(rv)) {
+          NS_WARNING("AttachHdr() Failed");
+          m_newMsgHdr = nullptr;
+          return;
+        }
         nsCOMPtr<nsIMsgFolderNotificationService> notifier(
             do_GetService("@mozilla.org/messenger/msgnotificationservice;1"));
         if (notifier) notifier->NotifyMsgAdded(m_newMsgHdr);
